{
  "technical_and_design_decisions": [
    "Target platform is Spring XD aligned to Spring Boot 1.2.0.RELEASE / Spring Framework 4.1.3 (per U5); the general Spring Framework 6 / Java 17 text in the specification is treated as background context, not as the target of this increment.",
    "U2: Add a 'codec' option to the hdfs-dataset sink that maps to Avro's CodecFactory; value 'none' (or null) disables the default Snappy compression, and any valid Avro codec name (e.g., deflate, bzip2) can be supplied.",
    "U3: Extend the Mail sink with a 'java-mail-properties' attribute that references a <util:properties/> bean; the properties are wired into the underlying Spring Integration mail adapters so that imaps/smtps with SSLSocketFactory settings work without code changes to adapters themselves.",
    "U4: Add partitionResultsTimeout to the module options metadata of the singlestep-partitioning job strategy so it is visible for all jobs that import it (including the 3 out-of-the-box jobs); regenerate/refresh the module metadata wiki page.",
    "U5: Manage all dependency versions via the existing property-based build files, aligning them with Boot 1.2.0's dependency management; fix resulting API and behavior changes and validate via the full regression suite.",
    "U6: Introduce an external YAML deployment-manifest file loaded at stream deployment time; manifest properties are parsed with SnakeYAML (via Boot's YAML support) and merged with/override inline deployment properties in the stream definition.",
    "U7: Implement a pluggable compression Codec abstraction in the message bus with gzip and zip implementations for both compression (producer side) and decompression (consumer side), selectable via stream/module options.",
    "U8: Expose compression options on the Rabbit source and sink modules that delegate to the U7 codec abstraction, keeping wire format compatible between compressed producers and consumers."
  ],
  "assumptions": [
    "A single developer (the author) performs all work; all figures are effort in work-hours, not elapsed calendar time.",
    "The developer is experienced with the Spring XD codebase, Spring Integration, Spring Batch, Hadoop/HDFS, Avro, JavaMail and RabbitMQ.",
    "Test infrastructure is already available and its procurement/setup cost is excluded: a Hadoop cluster with Sqoop and HDFS, a RabbitMQ broker, and secured (TLS) IMAP/SMTP test servers/mailboxes.",
    "For U1, representative benchmark datasets (in the tens of GB range) and basic data-loading tooling already exist; only benchmark-specific data preparation is counted.",
    "Documentation effort is limited to module README/wiki updates explicitly referenced by the stories; no formal product documentation overhaul is included.",
    "No UI changes are required; all features are configuration/metadata level.",
    "Estimates include self-verification (unit and integration testing) but exclude formal peer review, project management and release-coordination meetings.",
    "The existing build uses version properties as listed in U5, so the upgrade is primarily a property change plus compatibility remediation."
  ],
  "activities": [
    {
      "activity_id": "A-01",
      "activity_name": "U1: Benchmark planning and test data preparation",
      "activity_description": "Define benchmark scenarios and metrics for comparing the Sqoop import job vs. the jdbchdfs batch job (dataset sizes, concurrency, throughput/latency measures); prepare and stage representative test data in HDFS/relational source.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A-02",
      "activity_name": "U1: Benchmark environment configuration and execution",
      "activity_description": "Configure Sqoop and jdbchdfs jobs in XD, execute repeated benchmark runs for each scenario, and capture performance statistics (timings, throughput, resource usage).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-03",
      "activity_name": "U1: Results analysis and comparison report",
      "activity_description": "Aggregate and analyze collected statistics, produce comparison tables/charts and a written report contrasting Sqoop vs. jdbchdfs performance.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A-04",
      "activity_name": "U2: Implement configurable compression codec for hdfs-dataset sink",
      "activity_description": "Add a codec option to the hdfs-dataset sink for Avro files: allow disabling the default Snappy compression ('none') and allow specifying an alternative Avro codec, mapping the option to Avro's CodecFactory in the writer configuration.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A-05",
      "activity_name": "U2: Tests for hdfs-dataset codec configuration",
      "activity_description": "Unit and integration tests verifying default behavior (Snappy), disabled compression, and custom codec output (file readability and codec metadata in HDFS).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A-06",
      "activity_name": "U2: Documentation for hdfs-dataset codec options",
      "activity_description": "Update hdfs-dataset sink module documentation/wiki with the new codec option, allowed values and examples.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A-07",
      "activity_name": "U3: Implement java-mail-properties (TLS) support in Mail sink",
      "activity_description": "Add a java-mail-properties attribute to the Mail sink accepting a <util:properties/> bean reference and wire the properties into the Spring Integration mail adapters so secured imaps/smtps connections (SSLSocketFactory etc.) work.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A-08",
      "activity_name": "U3: Tests against secured IMAP/SMTP servers",
      "activity_description": "Integration tests against TLS-secured IMAP and SMTP servers verifying connection, authentication, send/receive paths and fallback behavior.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A-09",
      "activity_name": "U3: Documentation for Mail sink TLS configuration",
      "activity_description": "Document the java-mail-properties attribute with the SSL/TLS property example and link to the JavaMail property reference.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A-10",
      "activity_name": "U4: Expose partitionResultsTimeout as job metadata attribute",
      "activity_description": "Add partitionResultsTimeout to the module options metadata for jobs using the singlestep-partitioning strategy (including the 3 OOTB jobs that import it), verify it is surfaced, and update the metadata wiki page; includes a metadata verification test.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A-11",
      "activity_name": "U5: Update build dependency versions for Boot 1.2.0 alignment",
      "activity_description": "Set spring-boot to 1.2.0.RELEASE and update all ~35 listed dependency version properties (Spring 4.1.3, Spring Batch 3.0.2, Jackson 2.4.4, Tomcat 8.0.15, Jetty 9.2.4, etc.) in the build files; resolve dependency convergence issues.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A-12",
      "activity_name": "U5: Resolve code incompatibilities from the upgrade",
      "activity_description": "Fix compilation errors and adapt code/configuration for API and behavior changes introduced by Boot 1.2.0 and the upgraded dependencies (Spring Framework, Security, Data release train, servlet containers, etc.).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A-13",
      "activity_name": "U5: Regression testing and stabilization",
      "activity_description": "Run the full XD test suite and distributed runtime smoke tests, diagnose and fix regressions caused by the dependency upgrade until the build is stable.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A-14",
      "activity_name": "U5: Documentation and release notes for the upgrade",
      "activity_description": "Document the new baseline versions, migration notes and any behavior changes relevant to users/admins.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A-15",
      "activity_name": "U6: Design and implement YML deployment manifest support",
      "activity_description": "Design the external YAML deployment-manifest format; implement loading/parsing (SnakeYAML via Boot) and merge manifest properties with inline stream deployment properties at deployment time, including validation and error handling.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-16",
      "activity_name": "U6: Tests for YML deployment manifest",
      "activity_description": "Unit and integration tests for manifest parsing, property merging/overrides, missing/malformed file handling and end-to-end stream deployment using a manifest file.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A-17",
      "activity_name": "U6: Documentation for YML deployment manifest",
      "activity_description": "Document the manifest file format, usage in stream deployment commands and examples.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A-18",
      "activity_name": "U7: Implement gzip/zip message compression codecs",
      "activity_description": "Implement a pluggable compression codec abstraction in the message bus with gzip and zip compressors/decompressors, plus the stream/module options to select compression for message payloads.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-19",
      "activity_name": "U7: Tests for message compression codecs",
      "activity_description": "Unit tests for round-trip gzip/zip compression/decompression and integration tests verifying end-to-end compressed message flow and throughput characteristics.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A-20",
      "activity_name": "U7: Documentation for message compression",
      "activity_description": "Document compression options, supported codecs (gzip, zip) and performance trade-offs.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A-21",
      "activity_name": "U8: Add compression options to Rabbit source and sink modules",
      "activity_description": "Expose and wire compression/decompression options in the Rabbit source and sink modules, delegating to the U7 codec abstraction and ensuring wire-format compatibility between producers and consumers.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A-22",
      "activity_name": "U8: Tests for Rabbit source/sink compression",
      "activity_description": "Integration tests against a RabbitMQ broker covering compressed publish/consume, mixed compressed/uncompressed flows and error cases.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A-23",
      "activity_name": "U8: Documentation for Rabbit compression options",
      "activity_description": "Document the new compression options for the Rabbit source and sink modules with examples.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A-24",
      "activity_name": "Cross-increment integration and system verification",
      "activity_description": "Integrate all stories on the upgraded Boot 1.2.0 baseline, run end-to-end stream/job scenarios covering hdfs-dataset, mail, Rabbit compression and deployment manifests, and fix integration defects.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-25",
      "activity_name": "Build/CI updates and release packaging",
      "activity_description": "Update CI jobs for the new dependency set, verify distribution packaging (embedded containers, module descriptors) and prepare the increment build for release.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 330
  }
}
